preConditionHook:
// EEC E36. CountIF counts over bars 0..N-1 INCLUDING the current bar, and the
// counted condition is a true SERIES: its own [1] offsets shift with the
// counted bar, so position i tests high[i] > high[i+1] (EL_FEATURES `countif`,
// VERIFIED -- the frozen-offset model was refuted). The counted condition is
// on PRICES, which have real history back to the chart start, so no
// zero-filled variable mirror is needed; MaxBarsBack covers the window. The
// counts are EL numeric variables, kept as doubles. Every comparison below is
// an EL relational and goes through el_*; the operands are tick-grid prices or
// differences of two, so the 2.22e-12 tolerance is inert there either way.
bullTails = 0.0;
bearTails = 0.0;
for (int i = 0; i < (int)period; ++i) {
    if (el_gt(close[i], open[i])
        && el_gt(open[i] - low[i], close[i] - open[i])
        && el_gt(high[i], high[i + 1])) {
        bullTails += 1;
    }
    if (el_lt(close[i], open[i])
        && el_gt(high[i] - open[i], open[i] - close[i])
        && el_lt(low[i], low[i + 1])) {
        bearTails += 1;
    }
}
